import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    index += 1

    edges = []
    for _ in range(n - 1):
        u = int(data[index])
        v = int(data[index + 1])
        edges.append((u, v))
        index += 2

    m = int(data[index])
    index += 1

    ants = []
    for _ in range(m):
        a = int(data[index])
        b = int(data[index + 1])
        c = int(data[index + 2])
        d = int(data[index + 3])
        ants.append((a, b, c, d))
        index += 4

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Function to find connected components
    def bfs(start):
        visited = set()
        queue = deque([start])
        component = set()
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                component.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return component

    # Find all connected components
    components = []
    visited = set()
    for node in range(1, n + 1):
        if node not in visited:
            component = bfs(node)
            components.append(component)
            visited.update(component)

    # Check if we can assign colors to ants
    ant_to_component = {}
    for i, (a, b, c, d) in enumerate(ants):
        ant_to_component[i] = None
        for j, component in enumerate(components):
            if (a in component and b in component) or (c in component and d in component):
                if ant_to_component[i] is None:
                    ant_to_component[i] = j
                else:
                    print("NO")
                    return

    # Assign colors to ants
    component_to_color = {}
    color = 0
    for i, component_index in ant_to_component.items():
        if component_index not in component_to_color:
            component_to_color[component_index] = color
            color += 1

    # Determine which pair each ant uses
    result = []
    for i, (a, b, c, d) in enumerate(ants):
        component_index = ant_to_component[i]
        if (a in components[component_index] and b in components[component_index]):
            result.append(1)
        else:
            result.append(2)

    print("YES")
    for choice in result:
        print(choice)

if __name__ == "__main__":
    main()
